using System.Linq;using UnityEngine;using AntColony.Units;using AntColony.Core;public static class Sleep1114Bones {public static string Run(){var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.TrySleepingPose(out _,out _));var p=c.GetComponent<MeshyNativeMotionPlayer>();return string.Join("\n",p.NativeModel.GetComponentsInChildren<Transform>().Where(t=>new[]{"mixamorig:Head","mixamorig:Hips","mixamorig:LeftFoot","mixamorig:RightFoot","mixamorig:Spine2"}.Contains(t.name)).Select(t=>t.name+" "+t.position));}}
